=======
    'comment': [
        {
            // only treat (* ... *) as a comment if there is at least
            // one character between the delimiters:
            pattern: /(^|[^\\])\(\*[\s\S]+?\*\)/,
            lookbehind: true
        },
        {
            pattern: /(^|[^\\:])\/\/.*/,
            lookbehind: true
